// src/components/BudgetLimits.js
import React, { useState, useEffect } from "react";
import "./BudgetLimits.css";

function BudgetLimits({ formData }) {
  const categories = formData.spendingPriority
    ? Object.keys(formData.spendingPriority).filter(cat => formData.spendingPriority[cat] >= 3)
    : [];

  const [limits, setLimits] = useState({});

  useEffect(() => {
    const initial = {};
    categories.forEach(cat => initial[cat] = formData.budgetLimits?.[cat] || 0);
    setLimits(initial);
  }, [categories, formData]);

  const handleChange = (cat, value) => setLimits(prev => ({ ...prev, [cat]: Number(value) }));

  const handleSave = async () => {
    if (!categories.length) { alert("No categories selected with priority ≥ 3"); return; }

    const finalData = {
      incomeType: formData.incomeType || "No Income",
      category: formData.category,
      questionnaire: formData.questionnaire,
      spendingPriority: formData.spendingPriority,
      budgetLimits: limits,
      createdAt: new Date(),
      updatedAt: new Date(),
    };

    try {
      const res = await fetch("http://localhost:5000/api/userdata/save", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(finalData),
      });
      const data = await res.json();
      if (data.success) alert("Data saved successfully!");
      else alert("Failed to save data");
    } catch {
      alert("Server connection failed");
    }
  };

  return (
    <div className="budget-container">
      <h2 className="budget-title">Set Monthly Budget Limits</h2>
      {categories.length ? (
        <div className="budget-grid">
          {categories.map(cat => (
            <div key={cat} className="budget-card">
              <h3 className="budget-name">{cat}</h3>
              <input type="number" min={0} value={limits[cat] || 0} onChange={e => handleChange(cat, e.target.value)} className="budget-input" />
            </div>
          ))}
        </div>
      ) : (
        <p style={{ color: "red" }}>No categories selected with priority ≥ 3</p>
      )}
      <button className="save-button" onClick={handleSave}>Save Budget</button>
    </div>
  );
}

export default BudgetLimits;
